export async function runQueue(tasks, retries = 0) {
  const results = [];
  for (const task of tasks) {
    for (let attempt = 0; attempt <= retries; attempt++) {
      try { results.push(await task()); }
      catch (error) { if (attempt === retries) throw error; }
    }
  }
  return results;
}

